/* VIE UI — all mutations are local and explicit. No external service is called. */
(()=>{'use strict';
const C=window.VieCore;const STORE='vie-personal-v1';let state=C.seed();let locked=false;let uncertain=null;let recovery={raw:'',reason:''};let view='today';let week=C.monday(new Date());let projectFilter='all';let selectedProject=null;let onModalSave=null;let toastTimer;
const $=s=>document.querySelector(s);const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const attr=esc;const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(Number(n)||0);
const frDate=d=>{const dt=new Date(d+'T12:00:00');return Number.isNaN(dt.getTime())?esc(d):dt.toLocaleDateString('fr-FR',{day:'numeric',month:'short'});};
const today=()=>C.iso(new Date());const month=()=>today().slice(0,7);const iconMap={today:'◫',week:'▦',projects:'▣',study:'◈',career:'◉',life:'♡',finance:'◍',goals:'◇',ideas:'✧',settings:'⚙'};
const nav=[['today','Vue d’ensemble'],['week','Ma semaine'],['projects','Mes projets'],['study','Études'],['career','Candidatures'],['life','Vie & habitudes'],['finance','Finances'],['goals','Objectifs'],['ideas','Idées'],['settings','Réglages']];
const storage=()=>{try{return window.localStorage;}catch(err){return null;}};const loaded=C.loadStored(storage(),STORE);state=loaded.state;locked=loaded.locked;recovery={raw:loaded.raw,reason:loaded.reason};
// Écriture : succès UNIQUEMENT si le navigateur a relu les mêmes octets. Si le contenu stocké n'est pas vérifiable (uncertain), toute écriture ordinaire est bloquée jusqu'à une relecture réussie.
function persist(next){if(uncertain){showToast('Rien n’est enregistré : l’état du stockage est incertain (voir bandeau).');return false;}const r=C.saveStored(storage(),STORE,next,locked);if(r.ok)return true;if(r.uncertain){uncertain={reason:r.reason};showToast('Enregistrement incertain : '+r.reason+'. Plus rien n’est enregistré tant que ce n’est pas clarifié (bandeau).');return false;}showToast(locked?'Rien n’est enregistré : traite d’abord la sauvegarde illisible (bandeau).':'Enregistrement impossible : '+r.reason+'. Exporte tes données pour les conserver.');return false;}
// Changement transactionnel sur un BROUILLON : `state` pointe sur une copie pendant `mutate`, et n'est remplacé qu'après écriture confirmée ; sinon l'objet d'origine est conservé intact.
// Conséquence : un callback ne doit jamais garder une référence d'objet prise à l'ouverture d'un formulaire ; il retrouve son objet par identifiant À L'APPEL.
function commit(mutate,okMsg='Modifications enregistrées localement.'){const before=state,draft=C.structuredCopy(state);let ok=false;state=draft;try{ok=mutate()!==false;}catch(err){ok=false;}if(ok&&persist(draft)){if(okMsg)showToast(okMsg);render();return true;}state=before;render();return false;}
const gone=()=>{showToast('Élément introuvable : modification non appliquée.');return false;};
function renderRecovery(){return `<section class="warning-box" role="alert"><strong>Sauvegarde locale illisible.</strong> ${esc(recovery.reason||'contenu non reconnu')}. VIE affiche des données de démonstration et <b>n’enregistre plus rien</b> pour ne pas écraser ta sauvegarde. Tu peux copier ou télécharger le texte brut ci-dessous, ou repartir de zéro : la copie brute reste conservée dans ce navigateur.<div class="field wide"><label for="recovery-raw">Texte brut stocké</label><textarea id="recovery-raw" readonly rows="8">${esc(recovery.raw)}</textarea></div><div class="inline-actions">${btn('recovery-download','↧ Télécharger le texte brut','secondary')}${btn('reset','Conserver la copie et repartir de zéro','danger')}</div></section>`;}
function renderUncertain(){return `<section class="warning-box" role="alert" id="uncertain-banner"><strong>Enregistrement incertain.</strong> ${esc(uncertain.reason)}. VIE ne peut pas prouver ce que ton navigateur a réellement conservé : <b>plus aucune modification n’est enregistrée</b> et aucune restauration n’est affirmée. Les données affichées sont celles de la dernière sauvegarde confirmée. Exporte-les, puis relis le stockage local (ou recharge la page).<div class="inline-actions">${btn('export','↧ Exporter l’état affiché','secondary')}${btn('uncertain-recheck','Relire le stockage local','primary')}</div></section>`;}
// Sortie du mode incertain : lecture seule du stockage, jamais d'écriture ; l'affichage adopte ce que le navigateur contient réellement.
function recheckStorage(){if(!uncertain)return;const l=C.loadStored(storage(),STORE);if(l.unreadable){showToast('Le stockage reste illisible : rien n’a été modifié, l’écriture reste bloquée.');return;}if(l.raw!==JSON.stringify(state)&&!confirm('Le stockage contient des données différentes de celles affichées. Les afficher à la place ? Exporter d’abord l’état affiché si nécessaire.'))return;state=l.state;locked=l.locked;recovery={raw:l.raw,reason:l.reason};uncertain=null;render();showToast(l.locked?'Stockage relu : contenu illisible, mode récupération.':'Stockage relu : l’affichage correspond à ce que le navigateur a conservé.');}
function downloadRaw(){const blob=new Blob([recovery.raw],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='VIE_sauvegarde_illisible_'+today()+'.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);showToast('Texte brut téléchargé.');}
// Réinitialisation : en mode récupération, la copie brute est d'abord conservée et vérifiée sous une autre clé.
function resetAll(){if(uncertain){showToast('Réinitialisation bloquée : l’état du stockage est incertain (voir bandeau).');return;}let archived='';if(locked){if(!recovery.raw){showToast('Effacement impossible : le stockage local n’a pas pu être lu.');return;}const a=C.archiveCorrupt(storage(),STORE,recovery.raw,Date.now().toString(36));if(!a.ok){showToast('Effacement annulé : copie de secours impossible ('+a.reason+').');return;}archived=a.key;}const next=C.seed();const r=C.saveStored(storage(),STORE,next,false);if(!r.ok){if(r.uncertain){uncertain={reason:r.reason};render();}showToast('Réinitialisation impossible ('+r.reason+').');return;}state=next;locked=false;recovery={raw:'',reason:''};setView('today');showToast(archived?'Données réinitialisées. Copie conservée sous la clé '+archived+'.':'Données réinitialisées.');}
function showToast(msg){const n=$('#toast');if(!n)return;n.textContent=msg;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3300);}
function pageHeading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function btn(action,text,variant='primary',extra=''){return `<button type="button" class="btn ${variant}" data-action="${attr(action)}" ${extra}>${text}</button>`;}
function badge(text,cls=''){return `<span class="badge ${cls}">${esc(text)}</span>`;}
function pill(status){return status==='focus'?badge('Focus','accent'):status==='supervision'?badge('Supervision','green'):badge('Incubateur','gold');}
function selectOptions(opts,value){return opts.map(([v,l])=>`<option value="${attr(v)}"${String(value)===String(v)?' selected':''}>${esc(l)}</option>`).join('');}
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="field-${attr(name)}">${esc(label)}</label><input id="field-${attr(name)}" name="${attr(name)}" type="${attr(type)}" value="${attr(value)}" ${extra}></div>`;}
function selectField(name,label,opts,value=''){return `<div class="field"><label for="field-${attr(name)}">${esc(label)}</label><select id="field-${attr(name)}" name="${attr(name)}">${selectOptions(opts,value)}</select></div>`;}
function areaField(name,label,value=''){return `<div class="field wide"><label for="field-${attr(name)}">${esc(label)}</label><textarea id="field-${attr(name)}" name="${attr(name)}">${esc(value)}</textarea></div>`;}
const dayOpts=C.weekdays.map((d,i)=>[String(i),d]);
function setView(v){view=v;selectedProject=null;render();window.scrollTo(0,0);$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('open');$('#view').focus({preventScroll:true});}
function render(){const section=nav.find(([x])=>x===view)||nav[0];$('#breadcrumb').innerHTML=`Mon espace <span>/</span> ${esc(section[1])}`;$('#header-date').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});$('#nav').innerHTML=nav.map(([id,name])=>`<button class="nav-btn ${id===view?'active':''}" data-action="navigate" data-view="${id}"><span class="nav-icon">${iconMap[id]}</span>${esc(name)}</button>`).join('');let html='';switch(view){case'today':html=renderToday();break;case'week':html=renderWeek();break;case'projects':html=selectedProject?renderProjectDetail():renderProjects();break;case'study':html=renderStudy();break;case'career':html=renderCareer();break;case'life':html=renderLife();break;case'finance':html=renderFinance();break;case'goals':html=renderGoals();break;case'ideas':html=renderIdeas();break;case'settings':html=renderSettings();break;}$('#view').innerHTML=(locked?renderRecovery():'')+(uncertain?renderUncertain():'')+html;}
function renderToday(){const pending=state.tasks.filter(x=>!x.done).slice(0,5),active=state.projects.filter(p=>p.tier==='focus'),plan=C.buildWeekPlan(state,new Date()),index=(new Date().getDay()+6)%7,day=plan.days[index],done=C.countCompleted(state.tasks),apps=state.applications.filter(a=>a.sentAt&&a.status!=='brouillon').length;return `${pageHeading('TON TABLEAU DE BORD','Ta vie, à ton rythme.','Un espace clair pour faire avancer ce qui compte, sans t’épuiser.',btn('add-task','＋ Nouvelle tâche'))}
<div class="grid grid-kpis"><div class="kpi"><div class="kpi-icon">✦</div><small>PROJETS EN FOCUS</small><strong>${active.length}</strong><span>Maximum conseillé : 2</span></div><div class="kpi"><div class="kpi-icon">✓</div><small>TÂCHES RÉALISÉES</small><strong>${done}<span class="muted"> / ${state.tasks.length}</span></strong><span>Seulement ce qui est coché</span></div><div class="kpi"><div class="kpi-icon">◉</div><small>CANDIDATURES ENVOYÉES</small><strong>${apps}</strong><span>Comptabilisées après saisie</span></div><div class="kpi"><div class="kpi-icon">€</div><small>BUDGET PROJETS / MOIS</small><strong>${money(state.settings.budgetProjects)}</strong><span>Prévu, pas une dépense réelle</span></div></div>
<div class="grid dashboard-layout"><div class="stack"><section class="welcome"><div><div class="mini-label">L’ESSENTIEL CETTE SEMAINE</div><h2>Construis ton avenir.<br>Garde du temps pour vivre.</h2><p>Lernlabor, études, stage : des progrès réguliers valent mieux que dix chantiers ouverts en même temps.</p></div><div class="hero-action"><button data-action="navigate" data-view="week">Voir ma semaine →</button></div></section>
<section class="panel"><div class="panel-title"><h2>◉ Mes prochaines priorités</h2><button class="text-link" data-action="add-task">＋ Ajouter</button></div>${pending.length?pending.map(taskRow).join(''):`<div class="empty">Tout est terminé ! Ajoute une prochaine étape réaliste.</div>`}<p class="tagline">Ces tâches sont des propositions modifiables, pas des actions automatiquement réalisées.</p></section>
<section class="panel"><div class="panel-title"><h2>◫ Mon programme aujourd’hui</h2><button class="text-link" data-action="navigate" data-view="week">Calendrier complet</button></div>${day.blocks.length?day.blocks.map(b=>`<div class="list-row"><div><strong>${esc(b.name)}</strong><small>${b.fixed?'Plage réservée':'Créneau suggéré'} · ${esc(b.source)}</small></div><span class="badge ${b.kind==='work'?'accent':''}">${C.t(b.start)}–${C.t(b.end)}</span></div>`).join(''):'<div class="empty">Aucun bloc aujourd’hui.</div>'}${plan.conflicts.length?`<div class="warning-box">${plan.conflicts.length} conflit(s) dans la semaine à résoudre dans Réglages.</div>`:''}</section>
</div><div class="stack"><section class="panel"><div class="panel-title"><h2>Projets à suivre</h2><button class="text-link" data-action="navigate" data-view="projects">Tout voir</button></div>${active.map(p=>`<div class="project-item"><div class="project-avatar" style="background:${safeColor(p.color)}">${esc(p.short||p.name.slice(0,2))}</div><div class="project-details"><b>${esc(p.name)}</b><small>${esc(p.next)}</small></div><button data-action="project-open" data-id="${attr(p.id)}" aria-label="Ouvrir ${attr(p.name)}">→</button></div>`).join('')||'<div class="empty">Aucun projet en focus.</div>'}<div class="info-box">MainClip, Hermes et Publication restent visibles en supervision sans t’imposer du temps de développement quotidien.</div></section>
<section class="panel"><div class="panel-title"><h2>Mes habitudes</h2><button class="text-link" data-action="navigate" data-view="life">Suivi complet</button></div>${state.habits.slice(0,4).map(h=>{const n=C.habitCount(state,h.id,new Date());return `<div class="list-row"><div><strong>${esc(h.name)}</strong><small>${n} / ${esc(h.goal)} cette semaine</small></div>${badge(`${n}/${h.goal}`,n>=h.goal?'green':'')}</div>`;}).join('')}<div class="tagline">Les habitudes ne sont validées que si tu les coches.</div></section>
<section class="panel"><div class="panel-title"><h2>Rappel important</h2></div><p class="section-help">Ton planificateur bloque <strong>${esc(state.settings.sleepHours)} h de sommeil</strong> par nuit et protège les jours de travail long. Les horaires de travail et de cours doivent encore être confirmés.</p>${btn('navigate','Personnaliser les horaires','tertiary','data-view="settings"')}</section></div></div>`;}
function taskRow(t){return `<div class="task-item ${t.done?'done':''}"><input type="checkbox" class="check" data-action="task-check" data-id="${attr(t.id)}" ${t.done?'checked':''} aria-label="Terminer ${attr(t.title)}"><div class="task-main"><strong>${esc(t.title)}</strong><small>${t.projectId?esc(state.projects.find(p=>p.id===t.projectId)?.name||'Projet'):esc(t.category)} · ${esc(t.duration||45)} min${t.date?' · '+frDate(t.date):''}</small></div><div class="task-actions">${badge(t.priority||'normale',t.priority==='haute'?'accent':'')}<button class="text-link" data-action="edit-task" data-id="${attr(t.id)}">Modifier</button></div></div>`;}
function renderWeek(){const p=C.buildWeekPlan(state,week),start=C.monday(week),end=C.addDays(start,6);return `${pageHeading('PLANNING INTELLIGENT','Ta semaine',`${frDate(C.iso(start))} — ${frDate(C.iso(end))} · Les blocs « suggéré » restent déplaçables dans les prochaines versions.`,`${btn('week-prev','← Précédente','secondary')}${btn('week-current','Aujourd’hui','secondary')}${btn('week-next','Suivante →','secondary')}`)}<div class="info-box">Le programme est calculé localement. Travail et sommeil sont réservés avant les suggestions. <strong>Les cours non renseignés ne sont pas ajoutés.</strong> Ajoute tes créneaux dans Réglages pour fiabiliser le plan.</div><div class="calendar-days">${p.days.map(day=>`<div class="day-card ${day.date===today()?'today':''}"><div class="day-head"><span>${esc(day.name.slice(0,3))}</span><strong>${Number(day.date.slice(-2))}</strong></div>${day.blocks.map(b=>`<div class="time-block ${esc(b.kind)}${b.conflict?' conflict':''}"><small>${C.t(b.start)}–${C.t(b.end)}</small><strong>${esc(b.name)}</strong></div>`).join('')}<div class="day-actions"><button data-action="task-on-day" data-date="${attr(day.date)}">＋ Ajouter une tâche</button></div></div>`).join('')}</div><div class="grid two-col" style="margin-top:20px"><div class="panel"><div class="panel-title"><h2>À replanifier</h2></div>${p.unscheduled.length?p.unscheduled.map(x=>`<div class="list-row"><div><strong>${esc(x.title)}</strong><small>${esc(x.date)} · ${esc(x.reason)}</small></div></div>`).join(''):'<p class="section-help">Toutes les suggestions prévues ont trouvé un créneau.</p>'}</div><div class="panel"><div class="panel-title"><h2>Conflits et contraintes</h2></div>${p.conflicts.length?p.conflicts.map(x=>`<div class="warning-box">${esc(x)}</div>`).join(''):'<p class="section-help">Aucun conflit détecté sur les plages fixes renseignées.</p>'}<p class="small-note">Le plan ne remplace pas un agenda synchronisé : aucun trajet ni cours inconnu n’est inventé.</p>${btn('navigate','Modifier mes horaires','secondary','data-view="settings"')}</div></div>`;}
function safeColor(c){return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#eeeeff';}
function renderProjects(){const ps=state.projects.filter(x=>projectFilter==='all'||x.tier===projectFilter);return `${pageHeading('MES CHANTIERS','Tous mes projets','Un seul endroit pour suivre tes projets, les prioriser et retrouver leurs prochaines étapes.',btn('add-project','＋ Nouveau projet'))}<div class="filterbar">${[['all','Tous'],['focus','En focus'],['supervision','Supervision'],['incubator','Incubateur']].map(([id,label])=>`<button class="chip ${id===projectFilter?'selected':''}" data-action="project-filter" data-filter="${id}">${label}${id==='all'?` · ${state.projects.length}`:''}</button>`).join('')}</div><div class="grid project-grid">${ps.map(p=>`<article class="project-card"><div class="card-top"><div class="project-avatar" style="background:${safeColor(p.color)}">${esc(p.short||p.name.slice(0,2))}</div>${pill(p.tier)}</div><div><h3>${esc(p.name)}</h3>${badge(p.status)}</div><p>${esc(p.description)}</p><div class="footer"><span>${esc(p.domain)}</span><button data-action="project-open" data-id="${attr(p.id)}">Voir la fiche →</button></div></article>`).join('')}</div>`;}
function renderProjectDetail(){const p=state.projects.find(x=>x.id===selectedProject);if(!p){selectedProject=null;return renderProjects();}return `${pageHeading('PROJETS / FICHE',p.name,p.description,`${btn('project-back','← Tous les projets','secondary')}${btn('project-edit','Modifier la fiche','primary',`data-id="${attr(p.id)}"`)}`)}<div class="grid two-col"><div class="stack"><div class="panel"><div class="panel-title"><h2>Objectif & prochaine action</h2>${pill(p.tier)}</div><div class="goal-card"><b>Objectif du projet</b><p>${esc(p.goal)}</p></div><div class="goal-card"><b>Prochaine action concrète</b><p>${esc(p.next)}</p></div><div class="statline"><span>Situation actuelle</span>${badge(p.status)}</div><div class="statline"><span>Ambition / indicateur</span><strong>${esc(p.target)}</strong></div></div><div class="panel"><div class="panel-title"><h2>Jalons de progression</h2><button class="text-link" data-action="project-step-add" data-id="${attr(p.id)}">＋ Ajouter</button></div>${p.steps?.length?p.steps.map((s,i)=>`<div class="task-item ${s.done?'done':''}"><input type="checkbox" class="check" data-action="project-step-check" data-id="${attr(p.id)}" data-index="${i}" ${s.done?'checked':''} aria-label="${attr(s.name)}"><div class="task-main"><strong>${esc(s.name)}</strong><small>${s.done?'Déclaré terminé':'À valider'}</small></div><button class="text-link" data-action="project-step-delete" data-id="${attr(p.id)}" data-index="${i}">Retirer</button></div>`).join(''):'<div class="empty">Aucun jalon documenté.</div>'}</div></div><div class="stack"><div class="panel"><div class="panel-title"><h2>Confiance dans les informations</h2></div><div class="statline"><span>Source</span><b>${esc(p.source||'Manuel')}</b></div><div class="statline"><span>État / preuve</span><span class="muted-sm">Non synchronisé</span></div><p class="section-help">${esc(p.evidence||'Aucune preuve ajoutée')}</p><div class="warning-box">VIE ne lit pas encore les missions Hermes, GitHub ni les statistiques des réseaux. Les données sont éditables et doivent être vérifiées.</div></div><div class="panel"><div class="panel-title"><h2>Priorité de cette semaine</h2></div><div class="field"><label for="tier-select">Niveau de suivi</label><select id="tier-select" data-action="project-tier" data-id="${attr(p.id)}">${selectOptions([['focus','Focus actif'],['supervision','Supervision légère'],['incubator','Incubateur / pause']],p.tier)}</select></div><p class="small-note">Conseil : 2 projets en focus maximum.</p></div></div></div>`;}
function renderStudy(){return `${pageHeading('FORMATION','Mes études','Quatre matières à entretenir, et une pratique du code qui redevient autonome.',btn('navigate','Configurer mes cours','secondary','data-view="settings"'))}<div class="grid two-col"><div class="stack">${state.courses.map((c,i)=>`<div class="panel"><div class="panel-title"><h2>${i+1}. ${esc(c.name)}</h2>${badge(c.progress,'accent')}</div><p class="section-help">Prochaine étape : ${esc(c.next)}</p><div class="list-row"><span class="muted-sm">Révisions envisagées</span><b>${Number(c.timePerWeek)||0} min / semaine</b></div><div class="inline-actions">${btn('edit-course','Mettre à jour','tertiary',`data-id="${attr(c.id)}"`)}</div></div>`).join('')}</div><div class="stack"><div class="panel"><div class="panel-title"><h2>Réapprendre à coder</h2></div><p class="section-help">Des séances courtes, régulières et vérifiables — pas une promesse de tout réapprendre en un mois.</p><ol class="steps-list"><li><span class="step-num">1</span><span>Résoudre un problème simple sans l’aide de l’IA.</span></li><li><span class="step-num">2</span><span>Lire, expliquer et modifier du code existant.</span></li><li><span class="step-num">3</span><span>Construire un petit projet et expliquer tes choix techniques.</span></li></ol>${btn('add-task','Ajouter un exercice','primary','data-prefill="code"')}</div><div class="panel"><div class="panel-title"><h2>Équilibre formation / projets</h2></div><div class="info-box">Priorité aux échéances académiques. Si une semaine est chargée, VIE doit réduire les projets, pas le sommeil.</div></div></div></div>`;}
function renderCareer(){const rows=state.applications, sent=rows.filter(x=>x.sentAt&&x.status!=='brouillon').length,interviews=rows.filter(x=>x.status==='entretien').length;return `${pageHeading('AVENIR PROFESSIONNEL','Mes candidatures','Stages, Werkstudent et opportunités en informatique : un suivi réel, pas des chiffres inventés.',btn('add-application','＋ Ajouter une candidature'))}<div class="grid grid-kpis"><div class="kpi"><small>CANDIDATURES SAISIES</small><strong>${rows.length}</strong><span>Tous statuts</span></div><div class="kpi"><small>ENVOYÉES CONFIRMÉES</small><strong>${sent}</strong><span>Hors brouillons et refus</span></div><div class="kpi"><small>ENTRETIENS EN COURS</small><strong>${interviews}</strong><span>À préparer</span></div><div class="kpi"><small>RELANCES À PRÉVOIR</small><strong>${rows.filter(x=>x.followup&&x.followup<=today()&&!['refusée','offre'].includes(x.status)).length}</strong><span>Selon dates saisies</span></div></div><div class="panel"><div class="panel-title"><h2>Historique des candidatures</h2></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Entreprise</th><th>Poste</th><th>Envoyé le</th><th>Statut</th><th>Relance</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${esc(a.company)}</b></td><td>${esc(a.role)}</td><td>${a.sentAt?frDate(a.sentAt):'—'}</td><td>${badge(a.status,a.status==='offre'?'green':a.status==='refusée'?'red':'accent')}</td><td>${a.followup?frDate(a.followup):'—'}</td><td><button class="text-link" data-action="edit-application" data-id="${attr(a.id)}">Ouvrir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucune candidature enregistrée. Commence par en ajouter une, même en brouillon.</div>'}</div><div class="info-box">Une candidature n’est comptée comme envoyée que si tu renseignes le statut correspondant. Aucune candidature n’est envoyée depuis VIE.</div>`;}
function renderLife(){const base=C.monday(new Date()),dlist=Array.from({length:7},(_,i)=>C.iso(C.addDays(base,i)));return `${pageHeading('ÉQUILIBRE PERSONNEL','Prendre soin de moi','La santé et les relations ne sont pas des récompenses après le travail.',btn('navigate','Voir mon planning','secondary','data-view="week"'))}<div class="grid two-col"><div class="stack"><div class="panel"><div class="panel-title"><h2>Mes habitudes cette semaine</h2><small>Cliquer pour valider une activité réelle</small></div><div class="habit-line"><span></span>${C.weekdays.map(x=>`<small style="text-align:center;color:#989eaf">${x.slice(0,1)}</small>`).join('')}</div>${state.habits.map(h=>`<div class="habit-line"><div><strong style="font-size:12px">${esc(h.name)}</strong><div class="muted-sm">${C.habitCount(state,h.id,base)} / ${esc(h.goal)} objectif</div></div>${dlist.map(date=>`<input class="habit-dot" type="checkbox" data-action="habit-check" data-id="${attr(h.id)}" data-date="${attr(date)}" ${state.habitChecks[`${h.id}:${date}`]?'checked':''} aria-label="${attr(h.name)} ${date}">`).join('')}</div>`).join('')}<p class="small-note">Les cases représentent ta déclaration, pas une vérification automatique.</p></div><div class="panel"><div class="panel-title"><h2>Alimentation · Essensplan</h2>${badge('Intégration future','gold')}</div><p class="section-help">Ton système alimentaire existe déjà. Cette section évite de créer un deuxième stock ou une deuxième comptabilité.</p><div class="statline"><span>Budget alimentaire prévu</span><b>${money(state.settings.foodBudget)} / mois</b></div><div class="statline"><span>Magasin préféré</span><b>PENNY</b></div><p class="tagline">Menus, recettes et achats ne sont pas synchronisés avec VIE V1.</p></div></div><div class="stack"><div class="panel"><div class="panel-title"><h2>Corps & énergie</h2></div><div class="goal-card"><b>Sport régulier</b><p>Lundi, jeudi et samedi idéalement. Ajuster selon la récupération et les horaires réels.</p></div><div class="goal-card"><b>Sommeil</b><p>${esc(state.settings.sleepHours)} heures ciblées par nuit. Le programme évite de rogner le sommeil pour ajouter du travail.</p></div><div class="goal-card"><b>Perte de poids durable</b><p>Suivre les habitudes et le ressenti sans imposer une restriction arbitraire.</p></div></div><div class="panel"><div class="panel-title"><h2>Vie hors écran</h2></div><p class="section-help">Apprendre le piano, prendre soin de son style, voir ses proches, se reposer. Du temps est réservé dans le programme.</p>${btn('add-idea','Noter une envie','tertiary')}</div></div></div>`;}
function renderFinance(){const s=state.settings,spent=C.expensesInMonth(state,month()),budget=Number(s.budgetLiving)+Number(s.budgetProjects),by=C.expensesByCategory(state,month());return `${pageHeading('ARGENT & SÉRÉNITÉ','Mon budget','Distinguer enveloppes prévues et dépenses effectivement enregistrées.',btn('add-expense','＋ Enregistrer une dépense'))}<div class="grid grid-kpis"><div class="kpi"><small>ENVELOPPE DE VIE</small><strong>${money(s.budgetLiving)}</strong><span>Prévue / mois</span></div><div class="kpi"><small>BUDGET PROJETS</small><strong>${money(s.budgetProjects)}</strong><span>Prévu / mois</span></div><div class="kpi"><small>ÉCONOMIES</small><strong>${money(s.savingsMonthly||0)}</strong><span>Mises de côté / mois</span></div><div class="kpi"><small>ENVELOPPE TOTALE</small><strong>${money(budget)}</strong><span>À comparer aux revenus non saisis</span></div><div class="kpi"><small>DÉPENSES SAISIES CE MOIS</small><strong>${money(spent)}</strong><span>Ne représente pas le relevé bancaire</span></div></div><div class="grid two-col"><div class="stack"><div class="panel"><div class="panel-title"><h2>Dépenses réelles saisies</h2><small>${esc(month())}</small></div>${state.transactions.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Libellé</th><th>Catégorie</th><th>Montant</th><th></th></tr></thead><tbody>${state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${esc(x.date)}</td><td><b>${esc(x.label)}</b></td><td>${badge(x.category)}</td><td>${money(x.amount)}</td><td><button class="text-link" data-action="delete-expense" data-id="${attr(x.id)}">Retirer</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucune dépense réelle n’a été saisie. 0 € enregistré ne signifie pas 0 € dépensé.</div>'}</div><div class="panel"><div class="panel-title"><h2>Répartition des dépenses saisies</h2></div>${Object.keys(by).length?Object.entries(by).map(([key,value])=>`<div class="bar-row"><b>${esc(key)}</b><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,value/(spent||1)*100)}%"></div></div><b>${money(value)}</b></div>`).join(''):'<p class="section-help">Le graphique apparaîtra après la saisie de tes dépenses.</p>'}</div></div><div class="stack"><div class="panel"><div class="panel-title"><h2>Mes garde-fous</h2></div><div class="statline"><span>Alimentation</span><b>${money(s.foodBudget)} / mois</b></div><div class="statline"><span>Inclus dans les 800 € ?</span><strong>${s.foodIncludedInLiving===null?'À confirmer':s.foodIncludedInLiving?'Oui':'Non'}</strong></div><div class="statline"><span>Habits</span><strong>À définir</strong></div><div class="statline"><span>Revenu mensuel net</span><strong>Non renseigné</strong></div><div class="warning-box">Le budget total n’est pas ton solde bancaire. Aucun paiement ni connexion bancaire n’est effectué ici.</div>${btn('navigate','Modifier mes budgets','secondary','data-view="settings"')}</div><div class="panel"><div class="panel-title"><h2>Ambition de revenus</h2></div><div class="finance-big">${money(s.targetMonthly)} <span class="muted-sm">/ mois</span></div><p class="section-help">Objectif à 12 mois : au moins un projet, de préférence Lernlabor. Type : ${esc(s.targetType)}.</p></div></div></div>`;}
function renderGoals(){return `${pageHeading('VISION','Mes objectifs','Des directions mesurables et des étapes réalistes, sans pourcentages inventés.',btn('add-goal','＋ Nouvel objectif'))}<div class="grid two-col"><div class="stack">${state.goals.map(g=>`<div class="panel"><div class="panel-title"><h2>${esc(g.title)}</h2>${badge(g.horizon,'accent')}</div><div class="statline"><span>Statut</span><b>${esc(g.status)}</b></div><div class="statline"><span>Comment mesurer</span><b>${esc(g.metric)}</b></div><div class="statline"><span>Échéance</span><b>${g.deadline?frDate(g.deadline):'À définir'}</b></div>${btn('edit-goal','Modifier','tertiary',`data-id="${attr(g.id)}"`)}</div>`).join('')}</div><div class="stack"><div class="panel"><div class="panel-title"><h2>Pourquoi ces objectifs ?</h2></div><p class="section-help">Tu souhaites progresser sur tes projets et obtenir une situation professionnelle stable, tout en retrouvant du temps pour toi. Le plan peut ralentir un chantier, jamais effacer tes objectifs.</p></div><div class="panel"><div class="panel-title"><h2>Revue du dimanche</h2></div><ol class="steps-list"><li><span class="step-num">1</span><span>Quelles choses importantes ai-je réellement terminées ?</span></li><li><span class="step-num">2</span><span>Qu'est-ce qui a épuisé mon temps ou mon énergie ?</span></li><li><span class="step-num">3</span><span>Quelles deux priorités méritent mon attention la semaine prochaine ?</span></li></ol>${btn('add-review','Faire ma revue','primary')}</div></div></div>`;}
function renderIdeas(){return `${pageHeading('INCUBATEUR','Mes idées','Les noter, les retrouver, mais ne pas se sentir obligé de toutes les lancer.',btn('add-idea','＋ Ajouter une idée'))}<div class="grid project-grid">${state.ideas.map(i=>`<div class="project-card"><div class="card-top"><span class="project-avatar">✦</span>${badge(i.status,'gold')}</div><h3>${esc(i.title)}</h3><p>${esc(i.notes)}</p><div class="footer"><span>Idée personnelle</span><button data-action="edit-idea" data-id="${attr(i.id)}">Modifier →</button></div></div>`).join('')}</div>`;}
function renderSettings(){return `${pageHeading('PERSONNALISATION','Mes réglages','Tes informations restent dans ce navigateur. Tu peux exporter, importer et corriger tout ce qui est provisoire.')}
<div class="grid two-col"><div class="stack"><section class="panel"><div class="panel-title"><h2>Rythme & budget</h2>${btn('edit-settings','Modifier','tertiary')}</div><div class="statline"><span>Sommeil cible</span><strong>${esc(state.settings.sleepHours)} h / nuit</strong></div><div class="statline"><span>Vie courante</span><strong>${money(state.settings.budgetLiving)}</strong></div><div class="statline"><span>Projets</span><strong>${money(state.settings.budgetProjects)}</strong></div><div class="statline"><span>Alimentation</span><strong>${money(state.settings.foodBudget)}</strong></div><div class="statline"><span>Type revenu cible</span><strong>${esc(state.settings.targetType)}</strong></div></section><section class="panel"><div class="panel-title"><h2>Horaires de travail</h2>${btn('add-shift','＋ Créneau','tertiary')}</div>${state.settings.workShifts.map((s,i)=>`<div class="list-row"><div><strong>${esc(C.weekdays[s.day]||'Jour inconnu')} · ${esc(s.start)}–${esc(s.end)}</strong><small>${s.confirmed?'Confirmé manuellement':'À confirmer avec toi'}</small></div><div class="inline-actions"><button class="text-link" data-action="edit-shift" data-index="${i}">Éditer</button><button class="text-link" data-action="delete-shift" data-index="${i}">×</button></div></div>`).join('')}${!state.settings.workShifts.length?'<div class="empty">Aucun horaire de travail renseigné.</div>':''}</section><section class="panel"><div class="panel-title"><h2>Créneaux de cours</h2>${btn('add-class','＋ Cours','tertiary')}</div>${state.settings.courseBlocks.map((s,i)=>`<div class="list-row"><div><strong>${esc(s.title)} · ${esc(C.weekdays[s.day])}</strong><small>${esc(s.start)}–${esc(s.end)}</small></div><button class="text-link" data-action="delete-class" data-index="${i}">Retirer</button></div>`).join('')}${!state.settings.courseBlocks.length?'<div class="empty">À compléter pour que le programme évite tes cours.</div>':''}</section></div>
<div class="stack"><section class="panel"><div class="panel-title"><h2>Sauvegarde & confidentialité</h2></div><p class="section-help">VIE n’envoie aucune donnée à un serveur, sauf si tu actives toi-même le partage avec l’assistant Vie (désactivé par défaut ; voir ⚙ dans le panneau Vie). Les modifications sont sauvegardées dans le stockage local de ton navigateur, sur cet appareil.</p><div class="inline-actions">${btn('export','↧ Exporter JSON','primary')}${btn('import','↥ Importer JSON','secondary')}</div><div class="warning-box">Exporter régulièrement : la suppression des données du navigateur peut effacer ta progression. N’importe quel fichier importé remplace les données courantes après confirmation.</div><div class="divider"></div>${btn('reset','Réinitialiser la démo','danger')}</section><section class="panel"><div class="panel-title"><h2>Connexions possibles plus tard</h2></div>${['Hermes · missions & preuves','Essensplan · menus & stock','Google Agenda · calendrier','GitHub · projets & commits','ChatGPT · suivi et conseils'].map(x=>`<div class="list-row"><div><strong>${esc(x)}</strong><small>Aucune connexion effective en V1</small></div>${badge('Non connecté')}</div>`).join('')}</section><section class="panel"><div class="panel-title"><h2>Limites connues</h2></div><p class="section-help">Le site fonctionne sans IA, sans compte et sans Internet. L’assistant Vie (optionnel, serveur local requis) ne fait que proposer : aucune modification sans ta confirmation. Les dates de cours, les revenus et les trajets sont encore à renseigner.</p></section></div></div>`;}
function modal(title,html,callback){onModalSave=callback;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();const el=$('#modal-body').querySelector('input,select,textarea');if(el)el.focus();}
function data(form){return Object.fromEntries(new FormData(form).entries());}
function addOrEditTask(id,defaultDate='',preset=''){const existing=state.tasks.find(x=>x.id===id)||{id:C.uid(),title:preset==='code'?'Pratiquer le code sans IA':'',projectId:'',category:preset==='code'?'study':'projects',priority:'normale',duration:45,date:defaultDate,done:false,origin:'manuel',notes:''};modal(id?'Modifier une tâche':'Nouvelle tâche',`<div class="form-grid">${field('title','Intitulé',existing.title,'text','required maxlength="160"')}${selectField('projectId','Projet associé',[['','Aucun projet'],...state.projects.map(x=>[x.id,x.name])],existing.projectId)}${selectField('category','Catégorie',[['projects','Projet'],['study','Études'],['career','Carrière'],['wellness','Bien-être'],['rest','Vie personnelle']],existing.category)}${selectField('priority','Priorité',[['haute','Haute'],['normale','Normale'],['basse','Basse']],existing.priority)}${field('duration','Durée (minutes)',existing.duration,'number','min="15" max="480" required')}${field('date','Date facultative',existing.date,'date')}${areaField('notes','Notes',existing.notes)}</div>`,v=>{if(!v.title.trim())return false;const cur=id?state.tasks.find(x=>x.id===id):null;if(id&&!cur)return gone();const base=cur||existing;const next={...base,...v,title:v.title.trim(),duration:Math.max(15,Math.min(480,Number(v.duration)||45)),origin:id?base.origin:'manuel'};if(cur)state.tasks[state.tasks.indexOf(cur)]=next;else state.tasks.push(next);return true;});}
function editProject(id){const p=state.projects.find(x=>x.id===id)||{id:C.uid(),name:'',short:'',domain:'Projet',tier:'incubator',status:'À préciser',description:'',goal:'',next:'',target:'À préciser',source:'Saisie manuelle',evidence:'Aucune preuve',color:'#eeeeff',steps:[]};modal(id?'Modifier la fiche projet':'Nouveau projet',`<div class="form-grid">${field('name','Nom',p.name,'text','required maxlength="100"')}${field('domain','Domaine',p.domain,'text','maxlength="50"')}${selectField('tier','Priorité',[['focus','Focus actif'],['supervision','Supervision'],['incubator','Incubateur']],p.tier)}${field('status','État déclaré',p.status,'text','maxlength="100"')}${areaField('description','Description',p.description)}${areaField('goal','Objectif actuel',p.goal)}${areaField('next','Prochaine action',p.next)}${areaField('target','Indicateur de succès',p.target)}${areaField('evidence','Sources / preuves',p.evidence)}</div>`,v=>{if(!v.name.trim())return false;const cur=id?state.projects.find(x=>x.id===id):null;if(id&&!cur)return gone();const base=cur||p;const next={...base,...v,name:v.name.trim(),short:base.short||v.name.slice(0,2).toUpperCase(),source:'Saisie manuelle'};if(v.tier==='focus'&&state.projects.filter(x=>x.tier==='focus'&&x.id!==base.id).length>=2){showToast('Deux projets déjà en focus. Passe d’abord un autre en supervision.');return false;}if(cur)state.projects[state.projects.indexOf(cur)]=next;else state.projects.push(next);selectedProject=base.id;return true;});}
function addApplication(id){const a=state.applications.find(x=>x.id===id)||{id:C.uid(),company:'',role:'',status:'brouillon',sentAt:'',followup:'',url:'',notes:''};modal(id?'Mettre à jour une candidature':'Nouvelle candidature',`<div class="form-grid">${field('company','Entreprise',a.company,'text','required maxlength="120"')}${field('role','Intitulé du poste',a.role,'text','required maxlength="160"')}${selectField('status','Statut',[['brouillon','Brouillon'],['envoyée','Envoyée'],['entretien','Entretien'],['refusée','Refusée'],['offre','Offre']],a.status)}${field('sentAt','Date d’envoi',a.sentAt,'date')}${field('followup','Date de relance',a.followup,'date')}${field('url','Lien de l’offre',a.url,'url')}${areaField('notes','Notes / réponse',a.notes)}</div>${id?`<div style="margin-top:16px">${btn('delete-application','Supprimer cette candidature','danger',`data-id="${attr(a.id)}"`)}</div>`:''}`,v=>{if(!v.company.trim()||!v.role.trim())return false;if(['envoyée','entretien','offre','refusée'].includes(v.status)&&!v.sentAt){showToast('Indique la date d’envoi pour ce statut.');return false;}const cur=id?state.applications.find(x=>x.id===id):null;if(id&&!cur)return gone();const next={...(cur||a),...v,company:v.company.trim(),role:v.role.trim()};if(cur)state.applications[state.applications.indexOf(cur)]=next;else state.applications.push(next);return true;});}
function addExpense(){modal('Enregistrer une dépense réelle',`<div class="form-grid">${field('date','Date',today(),'date','required')}${field('amount','Montant en €','','number','required min="0.01" step="0.01"')}${field('label','Libellé','','text','required maxlength="120"')}${selectField('category','Catégorie',[['vie','Vie courante'],['projets','Projets'],['alimentation','Alimentation'],['habits','Habits'],['transport','Transport'],['autre','Autre']],'vie')}</div>`,v=>{if(!v.label.trim()||Number(v.amount)<=0||!Number.isFinite(Number(v.amount)))return false;state.transactions.push({id:C.uid(),date:v.date,label:v.label.trim(),amount:Math.round(Number(v.amount)*100)/100,type:'expense',category:v.category});return true;});}
function addGoal(id){const g=state.goals.find(x=>x.id===id)||{id:C.uid(),title:'',horizon:'3 mois',deadline:'',metric:'',status:'À préparer'};modal(id?'Modifier un objectif':'Nouvel objectif',`<div class="form-grid">${field('title','Objectif',g.title,'text','required maxlength="250"')}${field('horizon','Horizon',g.horizon)}${field('deadline','Échéance',g.deadline,'date')}${field('metric','Comment mesurer ?',g.metric)}${selectField('status','État',[['À préparer','À préparer'],['En cours','En cours'],['À mesurer','À mesurer'],['Terminé','Terminé']],g.status)}</div>`,v=>{if(!v.title.trim())return false;const cur=id?state.goals.find(x=>x.id===id):null;if(id&&!cur)return gone();if(cur)state.goals[state.goals.indexOf(cur)]={...cur,...v};else state.goals.push({...g,...v});return true;});}
function addIdea(id){const a=state.ideas.find(x=>x.id===id)||{id:C.uid(),title:'',notes:'',status:'En réflexion'};modal(id?'Modifier une idée':'Nouvelle idée',`<div class="form-grid">${field('title','Nom',a.title,'text','required maxlength="160"')}${selectField('status','Statut',[['En réflexion','En réflexion'],['À explorer','À explorer'],['Archivée','Archivée']],a.status)}${areaField('notes','Description',a.notes)}</div>`,v=>{if(!v.title.trim())return false;const cur=id?state.ideas.find(x=>x.id===id):null;if(id&&!cur)return gone();if(cur)state.ideas[state.ideas.indexOf(cur)]={...cur,...v};else state.ideas.push({...a,...v});return true;});}
function addClass(){modal('Ajouter un cours fixe',`<div class="form-grid">${field('title','Matière','Software Engineering','text','required maxlength="120"')}${selectField('day','Jour',dayOpts,'0')}${field('start','Début','09:00','time','required')}${field('end','Fin','11:00','time','required')}</div>`,v=>{if(!Number.isFinite(C.minTime(v.start))||!Number.isFinite(C.minTime(v.end))||C.minTime(v.end)<=C.minTime(v.start)){showToast('Heure de fin incorrecte.');return false;}state.settings.courseBlocks.push({...v,day:Number(v.day)});return true;});}
function editShift(index){const x=state.settings.workShifts[index]||{day:0,start:'09:00',end:'17:00',confirmed:false};modal(index>=0?'Modifier un horaire':'Ajouter un horaire',`<div class="form-grid">${selectField('day','Jour',dayOpts,String(x.day))}${field('start','Début',x.start,'time','required')}${field('end','Fin',x.end,'time','required')}${selectField('confirmed','Fiabilité',[['false','Provisoire'],['true','Confirmé par moi']],String(x.confirmed))}</div>`,v=>{if(!Number.isFinite(C.minTime(v.start))||!Number.isFinite(C.minTime(v.end))||C.minTime(v.end)<=C.minTime(v.start)){showToast('La fin doit être après le début.');return false;}const next={day:Number(v.day),start:v.start,end:v.end,confirmed:v.confirmed==='true'};if(index>=0){if(!state.settings.workShifts[index])return gone();state.settings.workShifts[index]=next;}else state.settings.workShifts.push(next);return true;});}
function editSettings(){const s=state.settings;modal('Rythme de vie et budget',`<div class="form-grid">${field('sleepHours','Sommeil cible / nuit (heures)',s.sleepHours,'number','min="7" max="10" step="0.5"')}${field('budgetLiving','Dépenses de vie / mois (€)',s.budgetLiving,'number','min="0" step="0.01"')}${field('budgetProjects','Budget projets / mois (€)',s.budgetProjects,'number','min="0" step="0.01"')}${field('savingsMonthly','Économies / mois (€)',s.savingsMonthly||0,'number','min="0" step="0.01"')}${field('foodBudget','Budget alimentation / mois (€)',s.foodBudget,'number','min="0" step="0.01"')}${selectField('foodIncludedInLiving','L’alimentation est-elle incluse dans la vie courante ?',[['','À confirmer'],['yes','Oui'],['no','Non']],s.foodIncludedInLiving===null?'':s.foodIncludedInLiving?'yes':'no')}${field('targetMonthly','Revenu cible / mois (€)',s.targetMonthly,'number','min="0"')}${selectField('targetType','Type de revenu',[['non précisé','À préciser'],['chiffre d’affaires','Chiffre d’affaires'],['bénéfice','Bénéfice net']],s.targetType)}</div>`,v=>{const num=k=>Math.max(0,Number(v[k])||0);state.settings={...state.settings,sleepHours:Math.max(7,Math.min(10,num('sleepHours'))),budgetLiving:num('budgetLiving'),budgetProjects:num('budgetProjects'),savingsMonthly:num('savingsMonthly'),foodBudget:num('foodBudget'),foodIncludedInLiving:v.foodIncludedInLiving===''?null:v.foodIncludedInLiving==='yes',targetMonthly:num('targetMonthly'),targetType:v.targetType};return true;});}
function addReview(){modal('Ma revue de la semaine',`<div class="form-grid">${areaField('wins','Ce que j’ai réellement accompli')}${areaField('pressure','Ce qui m’a trop pris de temps')}${areaField('priorities','Mes deux priorités suivantes')}</div>`,v=>{state.review.push({id:C.uid(),date:today(),...v});return true;});}
function editCourse(id){const a=state.courses.find(x=>x.id===id);if(!a)return;modal('Suivi de la matière',`<div class="form-grid">${field('name','Matière',a.name,'text','required')}${field('progress','Situation',a.progress)}${field('timePerWeek','Révision cible / semaine (min)',a.timePerWeek,'number','min="0" max="1000"')}${areaField('next','Prochaine échéance ou exercice',a.next)}</div>`,v=>{const cur=state.courses.find(x=>x.id===id);if(!cur)return gone();Object.assign(cur,v,{timePerWeek:Number(v.timePerWeek)||0});return true;});}
$('#modal-form').addEventListener('submit',e=>{if(e.submitter?.value!=='save')return;e.preventDefault();if(!onModalSave)return;const values=data(e.currentTarget);if(commit(()=>onModalSave(values))){$('#modal').close();}});
$('#modal').addEventListener('close',()=>{onModalSave=null;});
$('#file-import').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(uncertain){showToast('Import bloqué : l’état du stockage est incertain (voir bandeau).');return;}if(file.size>2_000_000){showToast('Fichier trop volumineux.');return;}try{const text=await file.text(),draft=C.validateImported(JSON.parse(text));if(locked){showToast('Import bloqué : traite d’abord la sauvegarde illisible (bandeau).');return;}if(!confirm('Importer ce fichier et remplacer toutes les données actuelles ? Exporter d’abord votre sauvegarde si nécessaire.'))return;if(!persist(draft)){render();return;}state=draft;setView('today');showToast('Données importées.');}catch(err){showToast(err instanceof SyntaxError?'Import refusé : fichier JSON illisible.':'Import refusé : '+err.message);}});
function doExport(){if(locked){showToast('Export désactivé : traite d’abord la sauvegarde illisible (bandeau).');return;}const content=JSON.stringify(state,null,2),blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='VIE_sauvegarde_'+today()+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);showToast('Sauvegarde JSON créée.');}
document.addEventListener('change',e=>{const a=e.target.dataset.action,id=e.target.dataset.id,checked=e.target.checked;if(a==='task-check'){commit(()=>{const t=state.tasks.find(x=>x.id===id);if(!t)return gone();t.done=checked;return true;},'');}else if(a==='habit-check'){const key=`${id}:${e.target.dataset.date}`;commit(()=>{state.habitChecks[key]=checked;},'');}else if(a==='project-step-check'){const i=Number(e.target.dataset.index);commit(()=>{const st=state.projects.find(x=>x.id===id)?.steps?.[i];if(!st)return gone();st.done=checked;return true;},'');}else if(a==='project-tier'){const tier=e.target.value;if(!state.projects.some(x=>x.id===id))return;if(tier==='focus'&&state.projects.filter(x=>x.tier==='focus'&&x.id!==id).length>=2){showToast('Maximum de deux projets actifs en focus.');render();return;}commit(()=>{const p=state.projects.find(x=>x.id===id);if(!p)return gone();p.tier=tier;return true;},'');}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.tagName==='INPUT'||b.tagName==='SELECT')return;const a=b.dataset.action,id=b.dataset.id,idx=Number(b.dataset.index);switch(a){case'navigate':setView(b.dataset.view);break;case'export':doExport();break;case'recovery-download':downloadRaw();break;case'uncertain-recheck':recheckStorage();break;case'import':$('#file-import').click();break;case'week-prev':week=C.monday(C.addDays(week,-7));render();break;case'week-next':week=C.monday(C.addDays(week,7));render();break;case'week-current':week=C.monday(new Date());render();break;case'add-task':addOrEditTask(null,'',b.dataset.prefill||'');break;case'task-on-day':addOrEditTask(null,b.dataset.date);break;case'edit-task':addOrEditTask(id);break;case'project-filter':projectFilter=b.dataset.filter;render();break;case'project-open':view='projects';selectedProject=id;render();window.scrollTo(0,0);break;case'project-back':selectedProject=null;render();break;case'add-project':editProject(null);break;case'project-edit':editProject(id);break;case'project-step-add':modal('Ajouter un jalon',field('name','Jalon','','text','required maxlength="160"'),v=>{if(!v.name.trim())return false;const p=state.projects.find(x=>x.id===id);if(!p)return gone();p.steps.push({name:v.name.trim(),done:false});return true;});break;case'project-step-delete':if(confirm('Retirer ce jalon ?')){commit(()=>{const p=state.projects.find(x=>x.id===id);if(!p||!p.steps[idx])return gone();p.steps.splice(idx,1);return true;},'');}break;case'add-application':addApplication(null);break;case'edit-application':addApplication(id);break;case'delete-application':if(confirm('Supprimer cette candidature ?')){if(commit(()=>{state.applications=state.applications.filter(x=>x.id!==id);},''))$('#modal').close();}break;case'add-expense':addExpense();break;case'delete-expense':if(confirm('Supprimer cette ligne de dépense ?')){commit(()=>{state.transactions=state.transactions.filter(x=>x.id!==id);},'');}break;case'add-goal':addGoal(null);break;case'edit-goal':addGoal(id);break;case'add-idea':addIdea(null);break;case'edit-idea':addIdea(id);break;case'edit-course':editCourse(id);break;case'edit-settings':editSettings();break;case'add-shift':editShift(-1);break;case'edit-shift':editShift(idx);break;case'delete-shift':if(confirm('Supprimer ce créneau de travail ?')){commit(()=>{state.settings.workShifts.splice(idx,1);},'');}break;case'add-class':addClass();break;case'delete-class':if(confirm('Retirer ce cours ?')){commit(()=>{state.settings.courseBlocks.splice(idx,1);},'');}break;case'add-review':addReview();break;case'reset':if(confirm(locked?'Sauvegarde illisible : une copie brute sera conservée dans ce navigateur, puis VIE repartira de zéro. Continuer ?':'Réinitialiser toutes les données VIE dans ce navigateur ? Exporter d’abord si nécessaire.'))resetAll();break;
}});
$('#menu-btn').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#backdrop').classList.toggle('open');});$('#backdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('open');});
// Pont facultatif pour l'assistant Vie (vie-assistant.js). Aucune écriture ne contourne `commit` : validation, transaction vérifiée, mode récupération et mode incertain restent ceux de la V1.
const VIEWS=nav.map(([id])=>id);
window.VieHost=Object.freeze({
  getState:()=>C.structuredCopy(state),
  status:()=>{let stored=null;try{const s=storage();stored=s?s.getItem(STORE)!==null:null;}catch(err){stored=null;}return{locked,uncertain:!!uncertain,reason:uncertain?uncertain.reason:locked?recovery.reason:'',hasStoredData:stored,view};},
  // `fn` reçoit le BROUILLON ; elle renvoie {ok:false,error,conflict} pour refuser. Rien n'est remplacé avant écriture confirmée.
  mutate:(fn,okMsg='')=>{if(locked)return{ok:false,error:'Mode récupération actif : aucune écriture (voir le bandeau).'};if(uncertain)return{ok:false,error:'Enregistrement incertain : aucune écriture tant que ce n’est pas clarifié (voir le bandeau).'};let refused=null;const ok=commit(()=>{const r=fn(state);if(r&&r.ok===false){refused=r;return false;}return true;},okMsg);return ok?{ok:true}:{ok:false,error:refused?refused.error:'Enregistrement impossible : rien n’a été modifié (voir le message).',conflict:!!(refused&&refused.conflict)};},
  navigate:v=>{if(!VIEWS.includes(v))return false;setView(v);return true;},
  showWeek:iso=>{try{week=C.monday(iso||new Date());}catch(err){return false;}view='week';selectedProject=null;render();window.scrollTo(0,0);return true;},
  exportBackup:()=>{if(locked)return false;doExport();return true;},
  toast:msg=>showToast(String(msg)),
});
render();
})();
